    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that Roblox offers in-app purchases of Robux, with a $4.99 package of 400 Robux and larger packages offering a more favorable exchange rate.",
      "stance": "risk",
      "quote": "amount you can purchase is 400 Robux for $4.99. The “exchange rate” is slightly more favorable if you decide to purchase more."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that Roblox offers a paid monthly subscription called Roblox Premium that includes a monthly deposit of Robux and costs between $4.99 and $19.99 per month.",
      "stance": "risk",
      "quote": "A paid monthly subscription to [*Roblox* Premium](https://www.roblox.com/premium/membership) includes a monthly deposit of Robux along with a variety of bonus features. *Roblox* Premium ranges in cost from $4.99 per month to $19.99 per month."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that spending can be blocked entirely by setting parental controls.",
      "stance": "mitigation",
      "quote": "don’t forget to set parental controls to manage how much your kids are allowed to spend (or block spending entirely)."
    },
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child in Roblox, and this feature can be turned off using parental controls.",
      "stance": "risk",
      "quote": "While [Allowed Experiences](https://en.help.roblox.com/hc/en-us/articles/8863284850196-Allowed-Experiences-Controls) and parental controls offer parents many great choices, there are always more steps you can take to ensure that your kids have appropriate video game experiences."
    }
  ]
}
